INSERT INTO `frases` (`id`, `frase`, `tipo_frase`, `year_id`, `created_by`, `updated_by`, `deleted_by`, `deleted_at`, `created_at`, `updated_at`) VALUES
('1', 'Es muy respetuoso con sus compañeros y docentes.', 'Fortaleza', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:10:48', '2015-09-08 03:45:26'),
('2', 'Es disciplinado.', 'Fortaleza', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:11:20', '2015-03-09 08:12:47'),
('3', 'Es responsable.', 'Fortaleza', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:11:39', '2015-03-09 08:12:50'),
('4', 'Tiene que mejorar su comportamiento.', 'Oportunidad', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:12:12', '2015-03-10 20:30:14'),
('5', 'Tiene ficha disciplinaria.', 'Debilidad', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:13:15', '2015-03-09 08:13:37'),
('6', 'Debe llegar temprano a la Institución.', 'Oportunidad', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:15:08', '2015-03-09 08:23:18'),
('7', 'Tiene reporte disciplinario.', 'Debilidad', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:15:34', '2015-03-09 08:15:34'),
('8', 'Es colaborador(a).', 'Fortaleza', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:16:07', '2015-03-09 08:24:08'),
('9', 'Evidencia la praxis de los valores.', 'Fortaleza', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:16:44', '2015-03-09 08:16:44'),
('10', 'Evidencia en su vida la fe.', 'Fortaleza', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:17:18', '2015-03-09 08:17:18'),
('11', 'Debe ajustar su corte de cabello a la filosofía institucional.', 'Oportunidad', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:17:55', '2015-09-07 22:19:59'),
('12', 'Debe dejar de comer chicle en clase.', 'Oportunidad', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:18:26', '2015-03-09 08:18:26'),
('13', 'Participa activamente en el desarrollo de las clases.', 'Fortaleza', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:18:50', '2015-03-09 08:19:02'),
('14', 'Interrumpe constantemente las clases.', 'Debilidad', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:19:27', '2015-03-09 08:19:27'),
('15', 'Es foco de indisciplina.', 'Debilidad', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:19:53', '2015-03-09 08:19:53'),
('16', 'Habla constantemente en formación.', 'Debilidad', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:20:38', '2015-03-09 08:20:38'),
('17', 'Constantemente presenta dificultades con el uniforme.', 'Debilidad', '1', NULL, NULL, NULL, NULL, '2015-03-09 08:21:37', '2015-03-09 08:21:37'),
